const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const types={group:'團體',personal:'個人'};
const mediaCache=new Map();
let mediaDBPromise;
function mediaDB(){if(!mediaDBPromise)mediaDBPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('wantoo-media',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return mediaDBPromise}
async function putMedia(blob,name,type){const db=await mediaDB(),id='media-'+Date.now()+'-'+Math.random().toString(36).slice(2);await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(blob,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});mediaCache.set(id,URL.createObjectURL(blob));return {id,name,type}}
function mediaTag(m,thumbnail=false){if(!m)return '<span class="media-placeholder">尚未附上影像</span>';const src=m.src||mediaCache.get(m.id)||'',attr=`${src?`src="${esc(src)}"`:''} data-media-id="${esc(m.id||'')}"`;return m.type==='video'?`<video ${attr} ${thumbnail?'muted':'controls'} playsinline preload="metadata" aria-label="${esc(m.name||'影片')}"></video>`:`<img ${attr} alt="${esc(m.name||'照片')}" loading="lazy" draggable="false">`}
function cover(t,result=false,thumbnail=false){const media=result?(t.resultMedia||[]):t.media;if(result&&!media?.length)return '<span class="record-empty" aria-label="文字紀錄，未附影像">文字紀錄</span>';return mediaTag(media?.[0],thumbnail)}
function isRecordEntry(t){return !!t.record||t.key?.startsWith('result:')}
function gallery(items){return items?.length?`<div class="media-gallery">${items.map(m=>`<figure>${mediaTag(m)}</figure>`).join('')}</div>`:''}
function mediaCredit(items){const sources=[...new Set((items||[]).map(m=>m.source).filter(Boolean))];return sources.length?`<p class="photo-credit">情境示意照，非真實活動現場 · ${sources.map((url,i)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">Pexels ${i+1}</a>`).join(' / ')}</p>`:''}
async function restoreMedia(){const refs=new Set();function scan(o){if(!o||typeof o!=='object')return;if(o.id&&typeof o.id==='string'&&o.id.startsWith('media-'))refs.add(o.id);Object.values(o).forEach(v=>{if(v&&typeof v==='object')scan(v)})}scan(state);if(!refs.size)return;try{const db=await mediaDB();await Promise.all([...refs].map(id=>new Promise(resolve=>{const request=db.transaction('files').objectStore('files').get(id);request.onsuccess=()=>{if(request.result)mediaCache.set(id,URL.createObjectURL(request.result));resolve()};request.onerror=resolve})));document.querySelectorAll('[data-media-id]').forEach(el=>{const url=mediaCache.get(el.dataset.mediaId);if(url)el.src=url})}catch{toast('此瀏覽器無法讀取本機影像。')}}
async function prepareMedia(file){const imageTypes=['image/jpeg','image/png','image/webp'],videoTypes=['video/mp4','video/webm'];if(!imageTypes.includes(file.type)&&!videoTypes.includes(file.type))throw Error('請選擇 JPG、PNG、WebP、MP4 或 WebM。');const video=videoTypes.includes(file.type);if(file.size>(video?20:10)*1024*1024)throw Error(video?'單支影片上限 20 MB。':'單張照片上限 10 MB。');let blob=file;if(!video){const bitmap=await createImageBitmap(file);const ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!blob)throw Error('照片處理失敗。')}return putMedia(blob,file.name,video?'video':'image')}
function mediaEditor(id,initial=[],limit=6,compact=false){let list=[...initial],busy=false;const host=$('#'+id);const draw=()=>{host.innerHTML=`<div class="media-editor ${compact?'compact':''}"><details class="media-add-menu"><summary aria-label="新增照片或影片">＋</summary><div class="media-add-options"><label class="media-album" tabindex="0" role="button">相簿<input class="media-file-input" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" multiple ${busy?'disabled':''} aria-label="從相簿選擇照片或影片"></label><small>照片 10 MB／影片 20 MB · 最多 ${limit} 個</small></div></details>${busy?'<small role="status">影像處理中…</small>':list.length?`<small>${list.length}/${limit}</small>`:''}<div class="attachment-previews">${list.map((m,i)=>`<div class="attachment-preview">${mediaTag(m,true)}<button type="button" data-remove="${i}" aria-label="移除${displayName(m.name)}">×</button></div>`).join('')}</div></div>`;host.querySelector('.media-album').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();host.querySelector('input').click()}};host.querySelector('input').onchange=async e=>{const files=[...e.target.files];if(list.length+files.length>limit){toast(`最多 ${limit} 個影像。`);e.target.value='';return}busy=true;draw();for(const file of files){try{list.push(await prepareMedia(file))}catch(error){toast(error.message||'影像儲存失敗，請檢查瀏覽器儲存空間。')}}busy=false;draw()};host.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(busy)return;list.splice(Number(b.dataset.remove),1);draw()})};draw();return {items:()=>[...list],busy:()=>busy,clear:()=>{list=[];draw()}}}

