function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function ageOf(dob,now=new Date()){const [y,m,d]=String(dob).split('-').map(Number);if(!y||!m||!d)return null;return now.getFullYear()-y-((now.getMonth()+1<m||(now.getMonth()+1===m&&now.getDate()<d))?1:0)}
function validBirth(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value)||value<='1899-12-31'||value>today())return false;const [y,m,d]=value.split('-').map(Number),date=new Date(y,m-1,d);return date.getFullYear()===y&&date.getMonth()===m-1&&date.getDate()===d}
