function authScreen(mode='login'){
 $('body').classList.add('auth-mode');$('body').classList.remove('exploring','detail-open','messaging','profile-page');
 $('#app').innerHTML=`<section class="auth-card"><a class="auth-brand">wantoo ↗</a><h1>${mode==='register'?'建立帳號':'歡迎回來'}</h1><p class="sub">本機互動原型；請用測試信箱與測試密碼。沒有真實信件寄送或線上帳號。</p><div class="tabs"><button id="auth-login" class="pill ${mode==='login'?'active':''}">登入</button><button id="auth-register" class="pill ${mode==='register'?'active':''}">註冊</button></div><form id="auth-form" class="profile-edit">${mode==='register'?'<label for="auth-handle">唯一帳號名稱</label><input id="auth-handle" name="handle" pattern="[a-zA-Z0-9_]{3,24}" required minlength="3" maxlength="24" placeholder="3–24 位英文、數字或底線">':''}<label for="auth-email">電子郵件</label><input id="auth-email" name="email" type="email" required autocomplete="email"><label for="auth-password">密碼</label><input id="auth-password" name="password" type="password" required minlength="8" autocomplete="${mode==='register'?'new-password':'current-password'}"><button class="primary">${mode==='register'?'建立測試帳號':'登入'}</button></form><button class="quiet" id="forgot-password">忘記密碼</button><p id="auth-error" role="alert"></p></section>`;
 $('#auth-login').onclick=()=>authScreen('login');$('#auth-register').onclick=()=>authScreen('register');$('#forgot-password').onclick=resetPassword;
 $('#auth-form').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target),email=data.get('email').trim().toLowerCase(),password=data.get('password');const button=e.target.querySelector('button');button.disabled=true;try{if(mode==='register'){const handle=data.get('handle').trim().toLowerCase();if(!/^[a-z0-9_]{3,24}$/.test(handle))throw Error('帳號格式不符。');if(authUsers.some(u=>u.email===email||u.handle===handle)||Object.values(accounts).includes(handle))throw Error('信箱或帳號已使用。');const salt=crypto.randomUUID();const user={id:crypto.randomUUID(),email,handle,salt,hash:await passwordHash(password,salt),verified:false};authUsers.push(user);saveAuth();verification(user)}else{const user=authUsers.find(u=>u.email===email);if(!user||await passwordHash(password,user.salt)!==user.hash)throw Error('信箱或密碼不正確。');if(!user.verified)verification(user);else loadUser(user)}}catch(error){$('#auth-error').textContent=error.message||'無法完成操作。'}finally{button.disabled=false}};
}
function verification(user){modal(`<h2>模擬信箱驗證</h2><p>尚未寄出真實信件。此按鈕僅供測試驗證後的流程。</p><button id="verify-user" class="primary">模擬驗證成功</button>`);$('#verify-user').onclick=()=>{user.verified=true;saveAuth();$('#modal').close();loadUser(user)}}
function resetPassword(){modal('<h2>模擬重設密碼</h2><p class="sub">無真實驗證信，本功能只供本機測試，不代表身分驗證。</p><form id="reset-password" class="profile-edit"><label>測試信箱<input name="email" type="email" required></label><label>新測試密碼<input name="password" type="password" minlength="8" required></label><button class="primary">模擬驗證並重設</button></form>');$('#reset-password').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target),u=authUsers.find(u=>u.email===d.get('email').trim().toLowerCase());if(!u)return toast('沒有這個本機測試帳號。');u.salt=crypto.randomUUID();u.hash=await passwordHash(d.get('password'),u.salt);saveAuth();$('#modal').close();toast('測試密碼已更新。')}}
function onboarding(){$('body').classList.add('auth-mode');$('body').classList.remove('exploring','detail-open','messaging','profile-page');$('#app').innerHTML='<section class="auth-card"><h1>建立你的個人檔案</h1><p>團體任務報名前，你可以確認將提供給發布者的基本資訊。出生年月日確認後無法修改，其他項目日後仍可編輯。</p><button id="begin-profile" class="primary">填寫個人檔案</button><button id="setup-logout" class="quiet">登出</button></section>';$('#begin-profile').onclick=editProfile;$('#setup-logout').onclick=signOut}
function gate(){if(!currentUser){authScreen();return false}if(!state.profile?.complete){onboarding();return false}$('body').classList.remove('auth-mode');return true}
function snapshotFor(t){const p=state.profile;return {nickname:p.name,handle:currentUser.handle,avatar:p.avatar||'',age:ageOf(p.dob),regions:p.regions,bio:p.bio,sex:t.genderRule?p.sex:undefined,sentAt:new Date().toISOString()}}
function snapshotHTML(s){return `<div class="application-snapshot">${s.avatar?`<img class="avatar" src="${esc(s.avatar)}" alt="報名頭貼">`:''}<dl><dt>暱稱／帳號</dt><dd>${esc(s.nickname)} / @${esc(s.handle)}</dd><dt>報名時年齡</dt><dd>${s.age} 歲</dd><dt>活動地區</dt><dd>${esc(s.regions)}</dd>${s.sex?`<dt>生理性別</dt><dd>${esc(s.sex)}</dd>`:''}<dt>自介</dt><dd>${esc(s.bio||'未填寫')}</dd></dl><small>版本：${esc(s.sentAt)}</small></div>`}
function confirmApplication(t,next){const snapshot=snapshotFor(t);modal(`<h2>${t.application?'更新報名資料':'確認本次提供的資料'}</h2><p class="sub">僅提供給「${displayName(t.owner)}」，不向其他參與者公開；不提供信箱與完整生日。</p>${snapshotHTML(snapshot)}<label class="check"><input id="agree-snapshot" type="checkbox">確認提供上述資料給此任務發布者</label><button id="submit-snapshot" class="primary">確認並繼續</button>`);$('#submit-snapshot').onclick=()=>{if(!$('#agree-snapshot').checked)return toast('請先確認本次提供的資料。');t.snapshotHistory??=[];if(t.applicationSnapshot)t.snapshotHistory.push(t.applicationSnapshot);t.applicationSnapshot=structuredClone(snapshot);save();$('#modal').close();next()}}

let page='explore',query='' ,index=0,room=null,friend=null,visitor=false,profileTab='portfolio',expandedTask=null,profileFocus=null;
function taskActivityTime(t){return Math.max(Number(t.activityAt)||0,...(state.messages['task-'+t.id]||[]).map(m=>Date.parse(m.time)||0),...(t.feed||[]).filter(f=>f.shared!==false).map(f=>Date.parse(f.time)||0))}
function touchTaskActivity(t){const sequence=Math.max(Number(state.activitySequence)||0,...state.tasks.map(x=>Number(x.activitySequence)||0))+1;state.activitySequence=sequence;t.activitySequence=sequence;t.activityAt=Date.now()}
function sortedActivityTasks(){return state.tasks.filter(hasTaskActivity).sort((a,b)=>(Number(b.activitySequence)||0)-(Number(a.activitySequence)||0)||taskActivityTime(b)-taskActivityTime(a))}
function reorderTaskRows(){const list=document.querySelector('.conversation-list');if(!list)return;for(const t of sortedActivityTasks()){const row=list.querySelector('[data-conversation="task-'+t.id+'"]');if(row)list.appendChild(row)}}
function hasTaskActivity(t){return t.joined||['pending','declined'].includes(t.application?.status)}
function updateTaskDot(){const button=document.querySelector('[data-page="community"]');if(button){const unread=state.tasks.some(t=>hasTaskActivity(t)&&t.activityUnread);button.classList.toggle('has-unread',unread);button.setAttribute('aria-label',unread?'任務交流，有未讀動態':'任務交流')}}
function openTaskActivity(key){const t=state.tasks.find(t=>'task-'+t.id===key);if(t){t.activityUnread=false;save()}room=key;community()}
function save(){updateTaskDot();try{localStorage.setItem(currentUser?'wantoo-state-'+currentUser.id:'wantoo-v1',JSON.stringify(state));return true}catch{toast('瀏覽器無法儲存，目前操作僅保留至頁面關閉。');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3200)}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal()}
$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
function title(){return ''}
function nav(p){if(p==='community')room=null;if(p!==page){room=null;friend=null;expandedTask=null;profileFocus=null}page=p;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));render();window.scrollTo(0,0)}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>nav(b.dataset.page));$('.brand').onclick=e=>{e.preventDefault();nav('explore')};
function render(){if(!gate())return;updateTaskDot();$('body').classList.toggle('exploring',page==='explore');$('body').classList.toggle('detail-open',page==='explore'&&expandedTask!==null);$('body').classList.toggle('messaging',page==='friends'||page==='community');$('body').classList.toggle('profile-page',page==='profile');({explore:explore,publish:publish,community:community,friends:friends,profile:profile,taskdetail:taskDetail})[page]()}
const accounts={'陳小山':'shan','吳沐':'mu','周雨':'rain','林以安':'yian'};
function filtered(){const q=query.trim().toLocaleLowerCase().replace(/^[#@]/,'');return state.tasks.filter(t=>!t.joined&&t.status!=='已完成'&&(!q||[t.id,t.title,t.desc,t.owner,accounts[t.owner]||''].some(v=>String(v).toLocaleLowerCase().includes(q))))}
function explore(){
 $('#app').innerHTML=`<div class="task-toolbar"><a class="brand-icon" href="#explore" aria-label="WANTOO 首頁">w<span>↗</span></a><form class="inline-search" id="search" role="search"><span aria-hidden="true">⌕</span><input id="query" name="query" type="search" aria-label="搜尋編號、任務關鍵字或帳號名稱" placeholder="搜尋編號、任務、帳號" value="${esc(query)}" autocomplete="off"><button type="button" id="clear-search" aria-label="清除搜尋">×</button></form><button id="publish-task" class="publish-icon" aria-label="發布任務" title="發布任務">＋</button></div><div id="account-results"></div><div class="explore-grid"><section id="deck"></section></div>`;
 $('#publish-task').onclick=()=>nav('publish');$('.brand-icon').onclick=e=>{e.preventDefault();query='';expandedTask=null;index=0;explore()};
 $('#search').onsubmit=e=>{e.preventDefault();$('#query').blur()};
 $('#query').oninput=e=>{query=e.target.value;index=0;expandedTask=null;drawDeck()};
 $('#clear-search').onclick=()=>{query='';index=0;expandedTask=null;$('#query').value='';drawDeck();$('#query').focus()};drawDeck();
}
function drawDeck(){
 $('body').classList.toggle('detail-open',expandedTask!==null);
 const list=filtered();index=((index%list.length)+list.length)%list.length||0;const t=list[index],q=query.trim().toLowerCase().replace(/^@/,'');
 accounts['林以安']=currentUser?.handle||'yian';const users=q?Object.keys(accounts).filter(n=>n.toLowerCase().includes(q)||accounts[n].includes(q)||(n==='林以安'&&state.profile?.name.toLowerCase().includes(q))):[];
 $('#account-results').innerHTML=users.map(n=>`<button class="account-result" data-account="${esc(n)}"><span class="avatar">${esc(n[0])}</span><span>${esc(n)} <small>@${accounts[n]}</small></span></button>`).join('');
 $('#clear-search').hidden=!query;
 const expanded=!!t&&expandedTask===t.id;
 $('#deck').innerHTML=t?`<article class="task-card ${expanded?'is-expanded':''}" id="swipe" tabindex="0" aria-label="任務卡，可左右滑動或使用方向鍵切換"><div class="art ${t.type}"><span class="tag">${types[t.type]}</span><span class="number">#${t.id}</span>${cover(t)}</div><div class="card-body"><div class="card-person"><button class="owner-link" data-account="${displayName(t.owner)}"><span class="avatar">${esc(t.owner[0])}</span>${displayName(t.owner)}</button></div><div class="card-reading"><h2 id="card-title">${esc(t.title)}</h2><div class="meta"><span>⌖ ${esc(t.place)}</span><span>◷ ${esc(t.date)}</span><span>◉ ${t.people}${t.capacity?'/'+t.capacity:''} 人</span></div><p id="card-description" class="task-description">${esc(t.desc)}</p><div class="expanded-media">${taskFacts(t)}</div><div class="expanded-media">${gallery((t.media||[]).slice(1))}${mediaCredit(t.media)}</div></div><div class="card-bottom"><button id="expand-task" class="quiet" aria-expanded="${expanded}" aria-controls="card-description" ${expanded?'':'hidden'}>${expanded?'收合詳情 ↑':'查看詳情 ↓'}</button><button class="join" id="join-task" data-join="${t.id}">${t.application?.status==='pending'?'申請審核中':'＋ 我也要'}</button></div></div></article>`:`<div class="empty">${query?'沒有符合的任務':'目前沒有新任務'}<br><button id="go-community" class="quiet">前往任務交流 →</button></div>`;
 bindTasks();document.querySelectorAll('[data-account]').forEach(b=>b.onclick=()=>account(b.dataset.account));
 if(t){
   const description=$('#card-description'),heading=$('#card-title');
   const longContent=description.scrollHeight>description.clientHeight+1||heading.scrollHeight>heading.clientHeight+1||heading.scrollWidth>heading.clientWidth+1||(t.media||[]).length>1||!!t.startAt||t.type==='personal';
   $('#expand-task').hidden=!expanded&&!longContent;
   $('#join-task').hidden=false;
   $('#expand-task').onclick=()=>{
     const card=$('#swipe'),opening=expandedTask!==t.id;
     if(opening)card.style.setProperty('--detail-image-height',(card.querySelector('.art').getBoundingClientRect().height||160)+'px');
     expandedTask=opening?t.id:null;
     card.classList.toggle('is-expanded',opening);$('body').classList.toggle('detail-open',opening);
     $('#expand-task').setAttribute('aria-expanded',String(opening));$('#expand-task').textContent=opening?'收合詳情 ↑':'查看詳情 ↓';
     $('#join-task').hidden=false;
   };
   const switchCard=direction=>{index+=direction;expandedTask=null;drawDeck();window.scrollTo(0,0)};
   $('#swipe').onkeydown=e=>{if(e.target!==$('#swipe'))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();switchCard(e.key==='ArrowRight'?1:-1);$('#swipe').focus({preventScroll:true})}};
   let x=null,y=null;
   $('#swipe').onpointerdown=e=>{if(e.target.closest('button,a,input,video'))return;x=e.clientX;y=e.clientY};
   $('#swipe').onpointercancel=()=>{x=null};
   $('#swipe').onpointerup=e=>{if(x!==null&&Math.abs(e.clientX-x)>65&&Math.abs(e.clientY-y)<65){switchCard(e.clientX<x?1:-1)}x=null};
 }else $('#go-community').onclick=()=>nav('community');
}
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(page==='explore'&&expandedTask===null)drawDeck()},100)});

function account(name){
 const f=state.friends.find(f=>f.name===name);if(name==='林以安'){$('#modal').close();visitor=true;nav('profile');return}
 modal(`<div class="account-head"><span class="avatar">${esc(name[0])}</span><div><h3>${esc(name)}</h3><small>@${esc(accounts[name]||name)}</small></div></div><p class="sub">尚無公開作品</p>${f?`<button id="account-action" ${f.state==='pending'?'disabled':''}>${{none:'申請好友',pending:'等待對方同意',incoming:'接受好友申請',friend:'傳送訊息'}[f.state]}</button>`:''}`);
 if(f)$('#account-action').onclick=()=>{if(f.state==='friend'){$('#modal').close();nav('friends');friend=name;friends()}else{f.state=f.state==='incoming'?'friend':'pending';save();account(name)}};
}
function bindTasks(){document.querySelectorAll('[data-join]').forEach(b=>b.onclick=()=>join(Number(b.dataset.join)))}
function full(t){return t.type!=='personal'&&t.capacity&&t.people>=t.capacity}
function finishJoin(t){if(full(t)){toast('任務人數已滿，無法加入。');return}t.participated=true;t.participationPublic=t.participationPublic!==false;t.joined=true;t.activityUnread=true;touchTaskActivity(t);t.people++;t.status=t.type==='personal'?'開放中':'進行中';expandedTask=null;save();render();toast('已加入，可在任務交流區查看。')}
function join(id){if(!gate())return;const t=state.tasks.find(t=>t.id===id);if(!t||t.joined)return;if(t.type==='personal'||t.application?.status==='pending'){joinAfterDisclosure(id);return}if(t.deadline&&new Date()>new Date(t.deadline))return toast('報名已截止。');const age=ageOf(state.profile.dob);if((t.minAge&&age<Number(t.minAge))||(t.maxAge&&age>Number(t.maxAge)))return toast('目前不符合此任務的年齡條件。');if(t.genderRule&&state.profile.sex!==t.genderRule)return toast('目前不符合此任務的性別條件。');confirmApplication(t,()=>joinAfterDisclosure(id))}
function joinAfterDisclosure(id){const t=state.tasks.find(t=>t.id===id);if(!t||t.joined||t.status==='已完成')return;if(full(t))return toast('任務人數已滿。');
 if(t.type==='personal'){if(!personalOpen(t))return toast('目前非任務開放期間。');delete t.application;finishJoin(t);return}
 if(t.application?.status==='pending'){modal(`<h2>申請審核中</h2><p>${esc(t.title)}</p><p class="sub">已送出申請，尚未加入任務。</p>${t.applicationSnapshot?`<details><summary>本次報名資料</summary>${snapshotHTML(t.applicationSnapshot)}<button id="pending-update">主動更新資料</button></details>`:''}${t.application.answers.map(a=>`<p><strong>${esc(a.question)}</strong><br>${esc(a.answer)}</p>`).join('')}<details><summary>原型測試：模擬發起人審核</summary><div class="actions"><button id="simulate-approve">模擬通過</button><button id="simulate-decline">模擬未通過</button></div><small>僅為本機示範，並非真實發起人的決定。</small></details>`);if(t.applicationSnapshot)$('#pending-update').onclick=()=>confirmApplication(t,()=>joinAfterDisclosure(t.id));$('#simulate-approve').onclick=()=>{if(full(t))return toast('人數已滿，無法通過。');t.application.status='approved';room=null;$('#modal').close();finishJoin(t)};$('#simulate-decline').onclick=()=>{t.application.status='declined';t.activityUnread=true;touchTaskActivity(t);room=null;save();$('#modal').close();render();toast('模擬結果：申請未通過，可重新填答。')};return}
 if(t.questions?.length){questionnaire(t);return}if(t.reviewMode==='review'){reviewApplication(t);return}finishJoin(t)
}
function reviewApplication(t){modal(`<h2>此任務需由發布者審核</h2><p>${esc(t.title)}</p><form id="review-application" class="profile-edit"><label for="app-note">留言給發布者（選填）</label><textarea id="app-note" maxlength="1000" placeholder="簡單介紹自己或參與的想法"></textarea><div class="actions"><button class="primary">送出申請</button><button type="button" id="skip-note">跳過留言並申請</button></div></form>`);const submit=note=>{t.application={status:'pending',answers:note?[{question:'申請留言',answer:note}]:[]};t.activityUnread=true;touchTaskActivity(t);save();$('#modal').close();render();toast('已送出申請，等待發布者審核。')};$('#review-application').onsubmit=e=>{e.preventDefault();submit($('#app-note').value.trim())};$('#skip-note').onclick=()=>submit('')}
function questionnaire(t,preview=false){const personal=t.type==='personal';modal(`<h2>${preview?'提問預覽':personal?'參與提問（選填）':'申請加入任務'}</h2><p class="sub">${esc(t.title)}</p><form id="application-form" class="profile-edit">${t.questions.map((q,i)=>`<label for="answer-${i}">${i+1}. ${esc(q)}</label><textarea id="answer-${i}" name="answer-${i}" ${personal?'':'required'} maxlength="1000" placeholder="請填寫回答"></textarea>`).join('')}<p class="sub">${preview?'預覽模式，不會送出。':personal?'不需審核，可回答或跳過後直接加入。':'填答送出後，等待發起人審核。'}</p><button class="primary">${preview?'完成預覽':personal?'加入任務':'送出申請'}</button>${personal&&!preview?'<button type="button" id="skip-personal">跳過並加入</button>':''}</form>`);$('#application-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),answers=t.questions.map((q,i)=>({question:q,answer:String(data.get('answer-'+i)||'').trim()}));if(!personal&&answers.some(a=>!a.answer))return toast('請回答所有問題。');if(!preview){if(personal)t.participationNotes=answers;else {t.application={status:'pending',answers};t.activityUnread=true;touchTaskActivity(t)}save()}$('#modal').close();if(!preview){if(personal)finishJoin(t);else{render();toast('問卷已送出，等待發起人審核。')}}};if(personal&&!preview)$('#skip-personal').onclick=()=>{t.participationNotes=[];$('#modal').close();finishJoin(t)}}
function publish(){
 $('#app').innerHTML=`<form id="publish-form" class="form"><label>任務類型<select id="type" name="type"><option value="group">團體任務</option><option value="personal">個人任務</option></select></label><label>任務名稱<input name="title" required maxlength="60"></label><label>任務內容<textarea name="desc" required maxlength="4000"></textarea></label><div id="task-media-editor"></div><label>地點<select id="location-mode" name="locationMode"><option value="">不限／未設定</option><option value="physical">實體</option><option value="online">線上</option></select></label><div id="physical-location" hidden><label>活動地區<input name="region" maxlength="60" placeholder="例如：台北市大安區"></label><label>詳細地點<input name="place" maxlength="120"></label></div><section id="group-settings"><div class="grid2"><label>開始時間<input name="startAt" type="datetime-local" required></label><label>結束時間<input name="endAt" type="datetime-local" required></label></div><label>報名截止（選填）<input name="deadline" type="datetime-local"></label><label>人數上限（含發布者，選填）<input name="capacity" type="number" min="1" max="10000" step="1"></label><label>費用<select id="fee-kind" name="feeKind"><option value="free">免費</option><option value="split">依實際費用均攤</option><option value="fixed">固定金額</option></select></label><label id="amount-wrap" hidden>每人金額（新台幣）<input id="fee-amount" name="feeAmount" type="number" min="0" step="1" disabled></label><label>費用用途與付款說明<textarea name="feeNote" maxlength="500"></textarea></label><label>加入方式<select id="screening" name="reviewMode"><option value="no">直接加入</option><option value="review">發布者審核，可留言</option><option value="yes">填寫問卷後審核</option></select></label><section id="question-builder" hidden><div id="questions"></div><button type="button" id="add-question">＋ 新增問題</button></section><label>性別條件（選填）<select name="genderRule"><option value="">不限，不提供性別資料</option value="女性">女性</option><option value="男性">男性</option></select></label><div class="grid2"><label>最低年齡（選填）<input name="minAge" type="number" min="0" max="120"></label><label>最高年齡（選填）<input name="maxAge" type="number" min="0" max="120"></label></div></section><section id="personal-settings" hidden><label>完成條件<input name="condition" maxlength="300" required disabled placeholder="怎樣算完成這次任務？"></label><div class="grid2"><label>開放時間<input name="openFrom" type="datetime-local" required disabled></label><label>截止時間<input name="openUntil" type="datetime-local" required disabled></label></div><label>建議花費時間<input name="duration" maxlength="60" disabled placeholder="例如：20 分鐘"></label><label>完成分享引導<textarea name="sharePrompt" maxlength="600" disabled placeholder="例如：今天觀察到什麼？"></textarea></label><label>預估自行花費（選填）<input name="estimatedCost" maxlength="120" disabled></label><small>期間內可不限次數完成。發布者每次完成須分享；一般參與者可只記錄完成。</small></section><label>準備／攜帶物品<textarea name="equipment" maxlength="500"></textarea></label><label>注意事項、其他資格或限制<textarea name="restrictions" maxlength="1000"></textarea></label><label>標籤（逗號分隔）<input name="tags" maxlength="100"></label><button class="primary">發布任務</button></form>`;
 const media=mediaEditor('task-media-editor',[],6);
 const setSection=(id,enabled)=>{const node=$('#'+id);node.hidden=!enabled;node.querySelectorAll('input,select,textarea').forEach(el=>el.disabled=!enabled)};
 const update=()=>{const personal=$('#type').value==='personal';setSection('group-settings',!personal);setSection('personal-settings',personal);$('#screening').onchange();$('#fee-kind').onchange()};
 $('#type').onchange=update;$('#location-mode').onchange=()=>{$('#physical-location').hidden=$('#location-mode').value!=='physical';$('#physical-location').querySelectorAll('input').forEach(i=>i.disabled=$('#location-mode').value!=='physical')};$('#location-mode').onchange();
 $('#fee-kind').onchange=()=>{const fixed=$('#type').value==='group'&&$('#fee-kind').value==='fixed';$('#amount-wrap').hidden=!fixed;$('#fee-amount').disabled=!fixed;$('#fee-amount').required=fixed};
 let qid=0;$('#add-question').onclick=()=>{if(document.querySelectorAll('.question-prompt').length>=10)return toast('最多 10 題。');$('#questions').insertAdjacentHTML('beforeend',`<div class="question-row"><label for="q-${++qid}">問題</label><div class="question-input"><input id="q-${qid}" class="question-prompt" required maxlength="200"><button type="button" class="remove-question" aria-label="刪除此題">×</button></div></div>`);document.querySelectorAll('.remove-question').forEach(b=>b.onclick=()=>b.closest('.question-row').remove())};
 $('#screening').onchange=()=>{const enabled=$('#type').value==='group'&&$('#screening').value==='yes';$('#question-builder').hidden=!enabled;if(enabled&&!document.querySelectorAll('.question-prompt').length)$('#add-question').onclick();document.querySelectorAll('.question-prompt').forEach(i=>i.disabled=!enabled)};
 $('#publish-form').onsubmit=e=>{e.preventDefault();if(media.busy())return toast('影像處理中。');const d=Object.fromEntries(new FormData(e.target)),personal=d.type==='personal';if(!d.title.trim()||!d.desc.trim())return toast('請填寫名稱與內容。');const from=personal?d.openFrom:d.startAt,to=personal?d.openUntil:d.endAt;if(!from||!to||new Date(to)<=new Date(from))return toast('結束時間需晚於開始時間。');if(personal&&!d.condition?.trim())return toast('請填寫完成條件。');if(d.deadline&&new Date(d.deadline)>new Date(d.startAt))return toast('報名截止不能晚於開始時間。');if(d.minAge&&d.maxAge&&Number(d.minAge)>Number(d.maxAge))return toast('年齡上下限不正確。');const capacity=!personal&&d.capacity?Number(d.capacity):null;if(capacity!==null&&(!Number.isInteger(capacity)||capacity<1||capacity>10000))return toast('人數上限需為 1～10000。');const questions=!personal&&d.reviewMode==='yes'?Array.from(document.querySelectorAll('.question-prompt')).map(i=>i.value.trim()):[];if(!personal&&d.reviewMode==='yes'&&(!questions.length||questions.some(q=>!q)))return toast('請填寫至少一個問題。');const t={...d,id:Math.max(...state.tasks.map(t=>t.id))+1,date:from.slice(0,10),capacity,media:media.items(),reviewMode:personal?'no':d.reviewMode,questions,place:d.locationMode==='online'?'線上':d.place||'不限地點',owner:'林以安',people:1,joined:true,participated:true,participationPublic:true,status:personal?'開放中':'招募中',completions:[],feed:[],queries:[],faq:[],icon:''};state.tasks.unshift(t);touchTaskActivity(t);save();nav('community');room='task-'+t.id;community()};
}
function personalOpen(t,now=new Date()){return (!t.openFrom||now>=new Date(t.openFrom))&&(!t.openUntil||now<=new Date(t.openUntil))}
function personalPanel(t){
 const owner=t.owner==='林以安',feed=(t.feed||[]).filter(f=>f.shared!==false);
 $('#messages').innerHTML=feed.map(f=>`<div class="bubble ${f.name==='林以安'?'mine':''}"><small>${displayName(f.name)} · ${f.kind==='announcement'?'公告':'完成分享'}</small><p>${esc(f.text)}</p>${gallery(f.media||[])}<time>${esc(new Date(f.time).toLocaleString('zh-TW',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}))}</time></div>`).join('')||'<p class="sub">尚無公告或完成分享</p>';
 $('#messages').scrollTop=$('#messages').scrollHeight;
 $('#personal-secondary').onclick=()=>owner?publishAnnouncement(t):personalQuestions(t);
 $('#personal-action').onclick=()=>completePersonal(t);
}
function publishAnnouncement(t){
 if(t.owner!=='林以安'||!t.joined)return;
 modal('<h2>發佈公告</h2><form id="announcement-form" class="profile-edit"><label>公告內容<textarea name="text" required maxlength="2000"></textarea></label><div id="announcement-media"></div><button class="primary">發佈公告</button></form>');
 const media=mediaEditor('announcement-media',[],6);let submitted=false;
 $('#announcement-form').onsubmit=e=>{e.preventDefault();if(submitted)return;if(media.busy())return toast('影像處理中。');const text=new FormData(e.target).get('text').trim();if(!text)return toast('請填寫公告內容。');submitted=true;t.feed??=[];t.feed.push({id:crypto.randomUUID(),kind:'announcement',name:'林以安',text,media:media.items(),time:new Date().toISOString(),shared:true});touchTaskActivity(t);save();$('#modal').close();community()};
}
function completePersonal(t){if(!t.joined||!personalOpen(t))return toast('請於開放期間加入後完成。');let submitted=false;const owner=t.owner==='林以安';modal(`<h2>完成這次任務</h2><p>${esc(t.condition||t.desc)}</p>${t.sharePrompt?`<p class="sub">${esc(t.sharePrompt)}</p>`:''}<form id="personal-completion" class="profile-edit"><label>成果／心得${owner?'（發布者須分享）':'（選填）'}<textarea name="text" maxlength="2000" ${owner?'required':''}></textarea></label><div id="completion-media"></div><label class="check"><input name="shared" type="checkbox" ${owner?'checked disabled':''}>分享完成到任務動態</label><label class="check"><input name="public" type="checkbox">公開為個人頁旅程紀錄</label><small>未公開紀錄保存在私人空間。任務動態與旅程紀錄分別設定。</small><button class="primary">${owner?'完成並分享':'確認完成'}</button></form>`);const media=mediaEditor('completion-media',[],6);$('#personal-completion').onsubmit=e=>{e.preventDefault();if(media.busy())return toast('影像處理中。');if(!personalOpen(t))return toast('任務已截止，無法新增完成紀錄。');if(submitted||!t.joined)return;const d=new FormData(e.target),text=d.get('text').trim(),shared=owner||d.has('shared'),pub=d.has('public');if((shared||pub)&&!text)return toast('分享時請留下一句心得。');submitted=true;const record={id:crypto.randomUUID(),text,media:media.items(),shared,public:pub,time:new Date().toISOString()};t.completions??=[];t.completions.push(record);if(shared){t.feed??=[];t.feed.push({...record,name:'林以安'});touchTaskActivity(t)}delete t.execution;t.participated=true;save();$('#modal').close();community()}}
function personalQuestions(t){t.queries??=[];modal(`<h2>詢問發布者</h2><p class="sub">問題只對你與發布者顯示，不會出現在完成動態。</p><form id="ask-form" class="profile-edit"><textarea name="question" required maxlength="1000" placeholder="你想詢問什麼？"></textarea><button class="primary">送出問題</button></form><h3>我的提問</h3>${t.queries.map((q,i)=>`<div class="question-item"><p>${esc(q.text)}</p><p class="sub">${q.reply?esc(q.reply):'等待回覆'}</p>${!q.reply?`<button data-reply="${i}" class="quiet">${t.owner==='林以安'?'回覆':'原型：模擬發布者回覆'}</button>`:''}</div>`).join('')||'<small>尚無提問</small>'}${t.owner==='林以安'?'<button id="add-faq">整理常見問答</button>':''}`);$('#ask-form').onsubmit=e=>{e.preventDefault();const text=new FormData(e.target).get('question').trim();if(!text)return;t.queries.push({text,time:new Date().toISOString(),reply:''});save();personalQuestions(t)};document.querySelectorAll('[data-reply]').forEach(b=>b.onclick=()=>{const index=Number(b.dataset.reply);modal('<h2>回覆提問</h2><form id="reply-form"><textarea name="reply" required maxlength="1000"></textarea><button class="primary">儲存回覆</button></form>');$('#reply-form').onsubmit=e=>{e.preventDefault();t.queries[index].reply=new FormData(e.target).get('reply').trim();save();personalQuestions(t)}});if(t.owner==='林以安')$('#add-faq').onclick=()=>{modal('<h2>新增常見問答</h2><p class="sub">請重新整理為一般問題，不包含提問者身分或私人內容。</p><form id="faq-form" class="profile-edit"><label>問題<input name="q" required maxlength="300"></label><label>回答<textarea name="a" required maxlength="1000"></textarea></label><button class="primary">公開常見問答</button></form>');$('#faq-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);t.faq??=[];t.faq.push({q:d.get('q').trim(),a:d.get('a').trim()});save();$('#modal').close()}}}

function previewMessage(key){const task=state.tasks.find(t=>'task-'+t.id===key);if(task&&!task.joined&&task.application)return task.application.status==='pending'?'申請已送出，等待審核':'申請未通過';if(task?.type==='personal'){const f=task.feed?.at(-1);return f?(f.name==='林以安'?'你':f.name)+'：'+f.text:'尚無完成分享'}const m=(state.messages[key]||[]).at(-1);return m?`${m.name==='林以安'?'你':m.name}：${m.text||(m.media?.length?'照片／影片':'')}`:'尚無訊息'}
function conversationRows(items,selected){return items.map(i=>`<button class="conversation-row ${selected===i.key?'selected':''}" data-conversation="${esc(i.key)}" aria-label="開啟${esc(i.name)}的對話"><span class="avatar">${i.media?mediaTag(i.media,true):esc(i.icon)}</span><span class="conversation-copy"><strong>${esc(i.name)}</strong><span>${esc(previewMessage(i.key))}</span></span><small>${esc(i.label)}</small>${i.unread?'<span class="activity-dot" aria-label="未讀動態"></span>':''}</button>`).join('')}
function inbox(items,selected,kind){
 const active=items.find(i=>i.key===selected),task=kind==='group'&&active?state.tasks.find(t=>'task-'+t.id===active.key):null;
 $('#app').innerHTML=`<div class="inbox ${active?'has-conversation':''}"><section class="conversation-list" aria-label="${kind==='group'?'任務交流':'好友訊息'}">${conversationRows(items,selected)||'<div class="empty">目前沒有對話</div>'}</section>${active?`<section class="conversation"><div class="conversation-header"><button id="back-inbox" class="quiet" aria-label="返回對話列表">←</button><span class="avatar">${active.media?mediaTag(active.media,true):esc(active.icon)}</span><div><strong>${esc(active.name)}</strong><small>${esc(active.label)}</small></div>${task?.joined?'<button class="quiet" id="group-task-info">任務詳情</button>':''}</div><div class="messages" id="messages"></div>${task&&!task.joined?'<div class="pending-task-actions"><button id="view-application">查看申請狀態</button></div>':task?.type==='personal'?`<div class="personal-chat-status">已完成 ${(task.completions||[]).length} 次${personalOpen(task)?'':' · 目前非開放期間'}</div><div class="personal-chat-actions"><button id="personal-secondary">${task.owner==='林以安'?'發佈公告':'詢問發布者'}</button><button id="personal-action" class="primary" ${personalOpen(task)?'':'disabled'}>完成任務</button></div>`:'<form class="compose" id="compose"><div id="chat-media-editor" class="chat-media-editor"></div><input name="message" aria-label="訊息內容" maxlength="1000" placeholder="輸入訊息…"><button class="primary" aria-label="送出訊息">↑</button></form>'}</section>`:'<div class="conversation-placeholder" aria-hidden="true">☏</div>'}</div>`;
 document.querySelectorAll('[data-conversation]').forEach(b=>b.onclick=()=>{if(kind==='group'){openTaskActivity(b.dataset.conversation)}else{friend=b.dataset.conversation.slice(3);friends()}});
 if(task?.joined)$('#group-task-info').onclick=()=>{page='taskdetail';render();window.scrollTo(0,0)};
 if(active){$('#back-inbox').onclick=()=>{if(kind==='group'){room=null;community()}else{friend=null;friends()}};if(task&&!task.joined){$('#messages').innerHTML=`<div class="bubble"><small>任務動態</small>${task.application?.status==='pending'?'申請已送出，等待發布者審核。通過後即可進入群組交流。':'申請未通過，可從任務面板重新申請。'}</div>`;$('#view-application').onclick=()=>join(task.id)}else if(task?.type==='personal')personalPanel(task);else chat(active.key)}
}
function taskDetail(){const t=state.tasks.find(t=>'task-'+t.id===room&&t.joined);if(!t){nav('community');return}$('#app').innerHTML=`<article class="task-detail-page"><button id="back-task-chat" class="quiet">← 返回對話</button><div class="result-cover large">${cover(t)}</div><h1>${esc(t.title)}</h1><div class="meta"><span>${types[t.type]} · #${t.id}</span><span>${esc(t.place)}</span><span>${esc(t.date)}</span><span>${t.people}${t.capacity?'/'+t.capacity:''} 人</span></div><p class="full-description">${esc(t.desc)}</p>${taskFacts(t)}${gallery((t.media||[]).slice(1))}${mediaCredit(t.media)}<p class="sub">發布者：${displayName(t.owner)}</p>${t.questions?.length?`<h3>${t.type==='personal'?'任務提示':'篩選問卷'}</h3><ol>${t.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ol>`:''}${t.participationNotes?.length?`<h3>我的參與備註</h3>${t.participationNotes.map(a=>`<p><strong>${esc(a.question)}</strong><br>${esc(a.answer||'未填寫')}</p>`).join('')}`:''}${t.applicationSnapshot?`<details><summary>本次已提供的報名資料</summary>${snapshotHTML(t.applicationSnapshot)}<button id="update-snapshot">主動更新這筆資料</button></details>`:''}${t.type==='personal'?`<button id="detail-ask">詢問發布者</button><h3>常見問答</h3>${(t.faq||[]).map(f=>`<p><strong>${esc(f.q)}</strong><br>${esc(f.a)}</p>`).join('')||'<small>尚無常見問答</small>'}`:''}<div class="task-exit-row"><button id="leave-task" ${t.owner==='林以安'?'disabled':''}>退出任務</button>${t.owner==='林以安'?'<p class="sub">發布者目前不能直接退出自己發布的任務。</p>':''}</div></article>`;if(t.applicationSnapshot)$('#update-snapshot').onclick=()=>confirmApplication(t,()=>{save();taskDetail();toast('已主動更新報名資料版本。')});if(t.type==='personal')$('#detail-ask').onclick=()=>personalQuestions(t);$('#back-task-chat').onclick=()=>{page='community';render()};$('#leave-task').onclick=()=>{modal('<h2>退出這個任務？</h2><p>退出後無法繼續使用任務交流，既有紀錄會保留在個人頁。</p><button id="confirm-leave" class="primary">確認退出</button>');$('#confirm-leave').onclick=()=>{t.joined=false;t.participated=true;t.people=Math.max(0,t.people-1);delete t.application;save();$('#modal').close();nav('community');toast('已退出任務。')}}}
function community(){$('body').classList.add('messaging');updateTaskDot();const items=sortedActivityTasks().map(t=>({key:'task-'+t.id,name:t.title,icon:t.icon,media:t.media?.[0],unread:!!t.activityUnread,label:!t.joined?(t.application?.status==='pending'?'待審核':'未通過'):t.type==='personal'?'任務動態':'團體群組'}));inbox(items,room,'group')}
function chat(key){
 const draw=()=>{$('#messages').innerHTML=(state.messages[key]||[]).map(m=>`<div class="bubble ${m.name==='林以安'?'mine':''}"><small>${displayName(m.name)}</small>${esc(m.text)}${gallery(m.media||[])}</div>`).join('')||'<p class="sub">尚無訊息</p>';$('#messages').scrollTop=$('#messages').scrollHeight};draw();
 const attachments=mediaEditor('chat-media-editor',[],3,true);
 $('#compose').onsubmit=e=>{e.preventDefault();if(attachments.busy())return toast('影像處理中，請稍候。');const text=new FormData(e.target).get('message').trim(),media=attachments.items();if(!text&&!media.length)return;state.messages[key]??=[];state.messages[key].push({name:'林以安',text,media,time:new Date().toISOString()});const task=state.tasks.find(t=>'task-'+t.id===key);if(task)touchTaskActivity(task);save();draw();attachments.clear();e.target.reset();if(task)reorderTaskRows();document.querySelectorAll('[data-conversation]').forEach(b=>{const line=b.querySelector('.conversation-copy>span');if(line)line.textContent=previewMessage(b.dataset.conversation)})}
}
function friends(){const items=state.friends.filter(f=>f.state==='friend').map(f=>({key:'dm-'+f.name,name:f.name,icon:f.name[0],label:''}));inbox(items,friend?'dm-'+friend:null,'friend')}
function taskFacts(t){return `<dl class="task-facts">${t.type==='personal'?`<dt>開放期間</dt><dd>${esc(t.openFrom||'未設定')} ～ ${esc(t.openUntil||'未設定')}</dd><dt>完成條件</dt><dd>${esc(t.condition||'依內容完成一次')}</dd>${t.duration?`<dt>建議時間</dt><dd>${esc(t.duration)}</dd>`:''}${t.estimatedCost?`<dt>預估自行花費</dt><dd>${esc(t.estimatedCost)}</dd>`:''}`:`<dt>時間</dt><dd>${esc(t.startAt||t.date)}${t.endAt?' ～ '+esc(t.endAt):''}</dd><dt>費用</dt><dd>${t.feeKind==='fixed'?'NT$ '+esc(t.feeAmount):t.feeKind==='split'?'實際費用均攤':'免費'} ${esc(t.feeNote||'')}</dd><dt>加入方式</dt><dd>${t.reviewMode==='yes'?'問卷審核':t.reviewMode==='review'?'發布者審核':'直接加入'}</dd>${t.genderRule?`<dt>性別條件</dt><dd>${esc(t.genderRule)}</dd>`:''}${t.minAge||t.maxAge?`<dt>年齡條件</dt><dd>${esc(t.minAge||0)}～${esc(t.maxAge||'不限')} 歲</dd>`:''}`} ${t.region?`<dt>地區</dt><dd>${esc(t.region)}</dd>`:''}${t.equipment?`<dt>攜帶／準備</dt><dd>${esc(t.equipment)}</dd>`:''}${t.restrictions?`<dt>注意事項／限制</dt><dd>${esc(t.restrictions)}</dd>`:''}</dl>`}
function profileEntries(){const tasks=state.tasks.filter(t=>t.joined||t.participated),journeys=[],privateEntries=[];for(const t of tasks){if(t.type==='personal'){for(const r of t.completions||[]){const entry={...t,key:'run:'+t.id+':'+r.id,record:r,reflection:r.text||'完成了一次任務',resultMedia:r.media,public:r.public,date:r.time.slice(0,10)};(r.public?journeys:privateEntries).push(entry)}}else if(t.reflection){const entry={...t,key:'result:'+t.id};(t.public?journeys:privateEntries).push(entry)}}return {tasks,journeys,privateEntries}}
let journeyListScroll=0;
function journeyList(entries){return `<div class="journey-list">${entries.map(t=>`<button class="journey-row" data-result="${esc(t.key)}"><span class="journey-copy"><strong>${esc(t.title)}</strong><span class="journey-preview">${esc(t.reflection||'')}</span><small>${esc(t.date)} · ${types[t.type]} · #${t.id}</small></span>${t.resultMedia?.length?`<span class="journey-thumbnail">${mediaTag(t.resultMedia[0],true)}${t.resultMedia.filter(m=>m.type!=='video').length>1?`<span class="journey-image-count" aria-label="共 ${t.resultMedia.filter(m=>m.type!=='video').length} 張圖片">+${t.resultMedia.filter(m=>m.type!=='video').length}</span>`:''}</span>`:''}</button>`).join('')||'<div class="profile-empty">尚無旅程紀錄</div>'}</div>`}
function journeyArticle(selected,entries){
 const at=entries.findIndex(t=>t.key===selected.key);
 $('#app').innerHTML=`<article class="journey-article"><button id="journey-back" class="quiet">← 返回${profileTab==='private'?'私人空間':'旅程紀錄'}</button><h1>${esc(selected.title)}</h1><p class="sub">${esc(selected.date)} · ${esc(state.profile.name)}</p><p class="journey-related">相關任務：${esc(selected.title)} · #${selected.id}</p><div class="journey-text">${esc(selected.reflection||'')}</div>${gallery(selected.resultMedia||[])}${!visitor?'<button id="journey-edit">編輯紀錄</button>':''}<nav class="journey-navigation" aria-label="文章導覽"><button id="journey-prev" ${at===0?'disabled':''}>上一篇</button><button id="journey-toc">目錄</button><button id="journey-next" ${at===entries.length-1?'disabled':''}>下一篇</button></nav></article>`;
 const open=key=>{profileFocus=key;profile();window.scrollTo(0,0)};
 $('#journey-back').onclick=()=>{profileFocus=null;profile();window.scrollTo(0,journeyListScroll)};
 $('#journey-prev').onclick=()=>{if(at>0)open(entries[at-1].key)};
 $('#journey-next').onclick=()=>{if(at<entries.length-1)open(entries[at+1].key)};
 $('#journey-toc').onclick=()=>{modal(`<h2>${profileTab==='private'?'私人紀錄目錄':'旅程目錄'}</h2><div class="journey-toc">${entries.map(t=>`<button data-journey="${esc(t.key)}" ${t.key===selected.key?'aria-current="page"':''}><strong>${esc(t.title)}</strong><small>${esc(t.date)}${t.key===selected.key?' · 閱讀中':''}</small></button>`).join('')}</div>`);document.querySelectorAll('[data-journey]').forEach(b=>b.onclick=()=>{$('#modal').close();open(b.dataset.journey)})};
 if(!visitor)$('#journey-edit').onclick=()=>{const task=state.tasks.find(t=>t.id===selected.id);if(selected.record)editPersonalRecord(task,selected.record.id);else editResult(task.id)};
}
function profile(){
 const {tasks,journeys,privateEntries}=profileEntries(),info=state.profile;
 if(visitor&&profileTab==='private')profileTab='portfolio';const shown=profileTab==='portfolio'?journeys:profileTab==='records'?tasks.filter(t=>t.participationPublic!==false).map(t=>({...t,key:'task:'+t.id})):privateEntries;
 const selected=shown.find(t=>t.key===profileFocus);
 if(selected&&(profileTab==='portfolio'||profileTab==='private')){journeyArticle(selected,shown);return}
 $('#app').innerHTML=`<section class="social-profile"><div class="profile-top"><strong>@${esc(currentUser.handle)}</strong>${visitor?'<span class="view-label">訪客預覽</span>':'<div><button id="edit-profile" class="small-button">編輯資料</button><button id="logout" class="quiet">登出</button></div>'}</div><div class="profile-identity"><span class="profile-avatar">${info.avatar?`<img src="${esc(info.avatar)}" alt="頭貼">`:esc(info.name[0])}</span><div><h1>${esc(info.name)}</h1><p>${esc(info.bio)}</p></div></div>${!visitor?`<div class="own-basic"><small>僅自己可見的報名基本資料</small><p>${ageOf(info.dob)} 歲 · ${esc(info.sex)} · ${esc(info.regions)}</p><small>出生日期已確認並鎖定；完整日期不會提供給發布者。</small></div>`:''}<div class="profile-stats"><div><strong>${state.followers?.length||0}</strong><span>位粉絲</span></div><div><strong>${journeys.length}</strong><span>紀錄</span></div><div><strong>${tasks.filter(t=>t.participationPublic!==false).length}</strong><span>任務</span></div></div><button id="visitor" class="profile-view-button">${visitor?'返回本人視角':'預覽公開個人頁'}</button></section><div class="profile-tabs" role="tablist">${[['portfolio','旅程紀錄'],['records','參與任務'],...(!visitor?[['private','私人空間']]:[])].map(([key,label])=>`<button role="tab" aria-selected="${key===profileTab}" data-tab="${key}">${label}</button>`).join('')}</div>${selected?`<article class="profile-detail"><button id="back-profile" class="quiet">← 返回列表</button><div class="result-cover large">${cover(selected,isRecordEntry(selected))}</div><div class="result-detail-body"><div class="meta">${types[selected.type]} · ${esc(selected.date)}</div><h2>${esc(selected.title)}</h2><p>${esc(selected.record?selected.reflection:profileTab==='records'?selected.desc:selected.reflection||selected.desc)}</p>${gallery((isRecordEntry(selected)?selected.resultMedia||[]:selected.media||[]).slice(1))}${!visitor?`<div class="actions">${selected.record?'<button id="edit-personal-record">編輯這次紀錄</button>':`<button id="toggle-participation">${selected.participationPublic===false?'公開參與任務':'隱藏任務'}</button><button id="edit-selected">${selected.type==='personal'?'前往任務動態':'編輯成果'}</button>`}</div>`:''}</div></article>`:(profileTab==='portfolio'||profileTab==='private')?journeyList(shown):`<div class="profile-grid">${shown.map(t=>`<div class="task-tile-wrap"><button class="result-tile" data-result="${esc(t.key)}"><span class="result-cover">${cover(t,isRecordEntry(t),true)}</span><strong>${esc(t.title)}</strong><small>${t.record?esc(t.date):types[t.type]}</small></button>${!visitor?`<button class="hide-profile-task quiet" data-hide-task="${t.id}">隱藏任務</button>`:''}</div>`).join('')||'<div class="profile-empty">此欄位尚無內容</div>'}</div>${!visitor?'<button id="manage-hidden-tasks" class="quiet">管理已隱藏任務</button>':''}`}`;
 document.querySelectorAll('[data-hide-task]').forEach(b=>b.onclick=()=>{const t=state.tasks.find(t=>String(t.id)===b.dataset.hideTask);if(!t)return;t.participationPublic=false;save();profile();toast('已隱藏任務，任務數已更新。')});
 if($('#manage-hidden-tasks'))$('#manage-hidden-tasks').onclick=manageHiddenTasks;
 $('#visitor').onclick=()=>{visitor=!visitor;profileFocus=null;profile()};if(!visitor){$('#edit-profile').onclick=editProfile;$('#logout').onclick=signOut}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{profileTab=b.dataset.tab;profileFocus=null;profile()});document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{journeyListScroll=window.scrollY;profileFocus=b.dataset.result;profile();window.scrollTo(0,0)});
 if(selected){$('#back-profile').onclick=()=>{profileFocus=null;profile()};if(!visitor){const t=state.tasks.find(t=>t.id===selected.id);if(selected.record)$('#edit-personal-record').onclick=()=>editPersonalRecord(t,selected.record.id);else{$('#toggle-participation').onclick=()=>{t.participationPublic=t.participationPublic===false;save();profileFocus=null;profile()};$('#edit-selected').onclick=()=>{if(t.type==='personal'){if(!t.joined)return toast('已退出此任務，請重新加入後查看動態。');nav('community');room='task-'+t.id;community()}else editResult(t.id)}}}}
}
function manageHiddenTasks(){
 if(visitor)return;
 const hidden=profileEntries().tasks.filter(t=>t.participationPublic===false);
 modal(`<h2>已隱藏任務</h2><p class="sub">隱藏任務不列入個人頁任務數，不影響任務參與或旅程紀錄。</p><div class="journey-toc">${hidden.map(t=>`<button data-restore-task="${t.id}"><strong>${esc(t.title)}</strong><small>恢復顯示</small></button>`).join('')||'<p>目前沒有隱藏任務</p>'}</div>`);
 document.querySelectorAll('[data-restore-task]').forEach(b=>b.onclick=()=>{const t=state.tasks.find(t=>String(t.id)===b.dataset.restoreTask);if(!t)return;t.participationPublic=true;save();profile();manageHiddenTasks()});
}
function editPersonalRecord(t,id){const r=t.completions.find(r=>r.id===id);modal(`<h2>編輯這次紀錄</h2><form id="edit-run" class="profile-edit"><textarea name="text" maxlength="2000">${esc(r.text)}</textarea><div id="run-media"></div><label class="check"><input type="checkbox" name="public" ${r.public?'checked':''}>公開到旅程紀錄</label><button class="primary">儲存</button></form>`);const media=mediaEditor('run-media',r.media||[],6);$('#edit-run').onsubmit=e=>{e.preventDefault();if(media.busy())return toast('影像處理中。');const d=new FormData(e.target),text=d.get('text').trim(),pub=d.has('public');if((r.shared||pub)&&!text)return toast('公開或已分享的紀錄需要心得。');r.text=text;r.public=pub;r.media=media.items();const feed=t.feed?.find(f=>f.id===r.id);if(feed){feed.text=text;feed.media=r.media}save();$('#modal').close();profileFocus=null;profile()}}

function editProfile(){
 const info=state.profile||{name:'林以安',bio:'喜歡散步、紙張，以及和有趣的人一起做事。'};
 modal(`<h2>編輯資料</h2><form id="profile-form" class="profile-edit"><label for="avatar-file">頭貼相片</label><input id="avatar-file" type="file" accept="image/jpeg,image/png,image/webp"><img id="avatar-preview" class="avatar-preview" alt="頭貼預覽" ${info.avatar?`src="${esc(info.avatar)}"`:'hidden'}><button type="button" id="remove-avatar">移除頭貼</button><section id="crop-editor" hidden><p class="sub">拖曳照片對位，調整縮放。圓框就是頭貼顯示範圍。</p><div class="crop-frame"><canvas id="crop-canvas" width="320" height="320" aria-label="頭貼裁切預覽，可拖曳調整位置"></canvas><div class="crop-mask"></div></div><label for="crop-zoom">縮放</label><input id="crop-zoom" type="range" min="1" max="4" step="0.01" value="1"><label for="crop-x">水平位置</label><input id="crop-x" type="range" min="-100" max="100" step="1" value="0"><label for="crop-y">垂直位置</label><input id="crop-y" type="range" min="-100" max="100" step="1" value="0"><div class="actions"><button type="button" id="crop-reset">重設位置</button><button type="button" id="crop-apply" class="primary">套用裁切</button></div></section><label for="profile-regions">活動地區（縣市／行政區，可用逗號分隔）</label><input id="profile-regions" name="regions" required maxlength="120" value="${esc(info.regions||'')}" placeholder="例如：台北市、新北市板橋區"><label for="profile-sex">生理性別</label><select id="profile-sex" name="sex" required><option value="">請選擇</option>${['女性','男性','其他','不願透露'].map(v=>`<option ${info.sex===v?'selected':''}>${v}</option>`).join('')}</select>${info.dob?`<label>年齡</label><p>${ageOf(info.dob)} 歲 · 出生日期已鎖定，不可修改</p>`:`<label for="profile-dob">出生年月日</label><input id="profile-dob" name="dob" type="date" min="1900-01-01" max="${today()}" required><p class="birth-warning">出生年月日只能填寫一次，確認後無法修改。其他人不會看到完整日期。</p><label class="check"><input name="confirmDob" type="checkbox" required>我已確認出生年月日正確，了解送出後無法修改</label>`}<label for="display-name">顯示名稱</label><input id="display-name" name="name" required maxlength="24" value="${esc(info.name)}"><label for="profile-bio">簡介</label><textarea id="profile-bio" name="bio" maxlength="150">${esc(info.bio)}</textarea><button class="primary">儲存</button></form>`);
 let avatar=info.avatar||'',bitmap=null,loading=false,loadVersion=0,drag=null;
 const canvas=$('#crop-canvas'),ctx=canvas.getContext('2d');
 const geometry=()=>{const scale=Math.max(320/bitmap.width,320/bitmap.height)*Number($('#crop-zoom').value);return {width:bitmap.width*scale,height:bitmap.height*scale}};
 const draw=()=>{if(!bitmap)return;const {width,height}=geometry(),x=(320-width)/2+Number($('#crop-x').value)/100*(width-320)/2,y=(320-height)/2+Number($('#crop-y').value)/100*(height-320)/2;ctx.fillStyle='#fff';ctx.fillRect(0,0,320,320);ctx.drawImage(bitmap,x,y,width,height)};
 const reset=()=>{$('#crop-zoom').value='1';$('#crop-x').value=$('#crop-y').value='0';draw()};
 const apply=()=>{if(!bitmap)return;draw();avatar=canvas.toDataURL('image/jpeg',.9);$('#avatar-preview').src=avatar;$('#avatar-preview').hidden=false;$('#crop-editor').hidden=true};
 ['crop-zoom','crop-x','crop-y'].forEach(id=>$('#'+id).oninput=draw);
 $('#crop-reset').onclick=reset;$('#crop-apply').onclick=apply;
 canvas.onpointerdown=e=>{if(!bitmap)return;drag={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId)};
 canvas.onpointermove=e=>{if(!drag||!bitmap)return;const {width,height}=geometry(),ratio=320/canvas.getBoundingClientRect().width;const clamp=v=>Math.max(-100,Math.min(100,v));if(width>320)$('#crop-x').value=clamp(Number($('#crop-x').value)+(e.clientX-drag.x)*ratio*200/(width-320));if(height>320)$('#crop-y').value=clamp(Number($('#crop-y').value)+(e.clientY-drag.y)*ratio*200/(height-320));drag={x:e.clientX,y:e.clientY};draw()};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;
 $('#remove-avatar').onclick=()=>{loadVersion++;loading=false;bitmap?.close();bitmap=null;avatar='';$('#avatar-preview').hidden=true;$('#avatar-file').value='';$('#crop-editor').hidden=true};
 $('#avatar-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){toast('請選擇 8 MB 內的 JPG、PNG 或 WebP。');return}const version=++loadVersion;loading=true;try{const next=await createImageBitmap(file);if(version!==loadVersion){next.close();return}bitmap?.close();bitmap=next;$('#crop-editor').hidden=false;reset()}catch{toast('無法讀取照片，請換一張。')}finally{if(version===loadVersion)loading=false}};
 $('#profile-form').onsubmit=e=>{e.preventDefault();if(loading)return toast('照片處理中，請稍候。');const d=new FormData(e.target),name=d.get('name').trim(),regions=d.get('regions').trim(),sex=d.get('sex'),dob=info.dob||d.get('dob');if(!name||!regions||!sex)return toast('請填寫暱稱、活動地區與生理性別。');if(!info.dob&&(!validBirth(dob)||!d.has('confirmDob')))return toast('請填寫有效出生日期並確認。');if(bitmap&&!$('#crop-editor').hidden)apply();state.profile={...info,name,regions,sex,dob,complete:true,bio:d.get('bio').trim(),avatar};save();bitmap?.close();$('#modal').close();if(!info.complete){visitor=false;nav('explore')}else profile()}
}

function editResult(id){const t=state.tasks.find(t=>t.id===id);modal(`<h2>編輯成果</h2><p class="sub">${esc(t.title)}</p><form id="result-form"><label for="reflection">成果與心得</label><textarea id="reflection" name="reflection" required maxlength="2000" placeholder="完成了什麼？學到了什麼？">${esc(t.reflection||'')}</textarea><div id="result-media-editor"></div><label class="check"><input name="public" type="checkbox" ${t.public?'checked':''}>公開到作品集，讓訪客看見</label><p class="sub">不公開的心得保存在私人空間；參與任務的公開設定可另外調整。</p><button class="primary">儲存成果，標記完成</button></form>`);const resultMedia=mediaEditor('result-media-editor',t.resultMedia||[],6);$('#result-form').onsubmit=e=>{e.preventDefault();if(resultMedia.busy())return toast('影像處理中，請稍候。');const d=new FormData(e.target),r=d.get('reflection').trim();if(!r)return toast('請先寫下一點成果與心得。');t.resultMedia=resultMedia.items();t.reflection=r;t.public=d.has('public');t.status='已完成';save();$('#modal').close();profile();toast('成果已儲存。')}}
$('#rules').onclick=()=>modal(`<div class="eyebrow">WANTOO / V1.0 PROTOTYPE</div><h2>這個原型，如何運作？</h2><h3>已確認的方向</h3><ul class="rules-list"><li>單卡探索、原位搜尋與卡內展開詳情；「我也要」統一顯示在卡片底部，長內容可展開與收合。加入後移至任務交流區。</li><li>團體、個人兩種任務；團體使用群組，個人僅顯示完成分享動態並提供獨立提問。</li><li>好友申請經雙方同意才可私訊；訊息列表只顯示已通過的好友，通知位置尚未決定。</li><li>本人可查看旅程紀錄、參與任務與私人空間；訪客可看公開旅程紀錄與參與任務，不能進入私人空間。作品來自完成任務後整理的成果與心得。</li></ul><h3>本原型的暫定規則</h3><ul class="rules-list"><li>滑動只切換卡片，不代表加入或拒絕。</li><li>加入方式分為直接加入、不提問但需審核、填寫問卷後審核。團體任務的問卷暫定文字題必填、最多 10 題，由發起人審核；個人任務直接加入，完成後自願分享；本機原型提供明確標示的模擬審核。發布者自動加入。團體任務可設定人數上限，暫定包含發布者；待審核不占名額，通過時再檢查容量。退出保留歷史紀錄；發布者退出、取消與候補尚未定案。</li><li>完成與公開由本人操作，只改變自己的紀錄。多人任務的共同結案、期限與權限尚未定案。</li><li>個人挑戰各自執行，共用成果交流區。個人任務不需審核；加入即代表參與意願，不需另外開始；期間內可不限次數記錄完成，發布者每次完成須分享。截止後暫不接受新增完成紀錄。照片／影片僅保存在本機；任務動態小點為本機未讀狀態；推播、檢舉與封鎖未納入本次原型。</li></ul><h3>示範資料與限制</h3><p class="sub">所有人物、訊息與任務都是示例。文字與影像僅存在此瀏覽器（localStorage／IndexedDB），註冊、登入、信箱驗證及忘記密碼均為本機模擬；無伺服器、跨裝置同步或真實隱私權限；訪客切換僅展示畫面規則。原對話部分規格只剩無法展開的引用，未將其視為已確認內容。</p><button class="danger" id="reset">重設所有示例資料</button>`);document.addEventListener('click',e=>{if(e.target.id==='reset'){modal('<h2>重設示例資料？</h2><p>將移除本機新增的任務、訊息與心得，恢復初始示例。</p><button id="confirm-reset" class="primary">確認重設</button>')}if(e.target.id==='confirm-reset'){const retainedProfile=state.profile;state=freshState();state.profile=retainedProfile;normalizeTasks();save();room=null;friend=null;index=0;expandedTask=null;query='';$('#modal').close();render();toast('已恢復示例資料。')}});

restoreMedia();

if(currentUser)loadUser(currentUser);else render();
